mapper.select:
SELECT r.id,
       r.type,
       w.name AS warehouseName,
       l.code AS locationCode,
       p.code AS partCode,
       p.name AS partName,
       r.quantity,
       r.remark,
       r.created_at AS createdAt
FROM stock_record r
JOIN warehouse w ON w.id = r.warehouse_id
JOIN location l ON l.id = r.location_id
JOIN part p ON p.id = r.part_id

    AND r.type = #{q.type}
    AND r.warehouse_id = #{q.warehouseId}
    AND r.location_id = #{q.locationId}
    AND r.part_id = #{q.partId}
    AND r.created_at >= #{q.startTime}
    AND r.created_at <= #{q.endTime}

ORDER BY r.created_at DESC, r.id DESC
